```python
# Function to check if a number is prime
def is_prime(n):
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    max_divisor = int(n ** 0.5) + 1
    for divisor in range(3, max_divisor, 2):
        if n % divisor == 0:
            return False
    return True

# Count the number of two-digit prime numbers with a ones digit of 1
count = 0
for number in range(10, 100):
    if is_prime(number) and str(number).endswith('1'):
        count += 1
print(count)
